-- The preserved editor's section headers, spacing and palette in native controls.
local wx=require('wx');local Themes=require('Manual.Themes');local Chrome={};
function Chrome.heading(parent,text,editor)
    local panel=Themes.role(wx.wxPanel(parent,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(-1,36)),'heading');local box=wx.wxBoxSizer(wx.wxVERTICAL);panel:SetSizer(box);local label=Themes.role(wx.wxStaticText(panel,wx.wxID_ANY,text),'heading');local font=wx.wxFont(10,wx.wxFONTFAMILY_DEFAULT,wx.wxFONTSTYLE_NORMAL,wx.wxFONTWEIGHT_BOLD,false,'Segoe UI');label:SetFont(font);font:delete();box:Add(label,0,wx.wxALL,7);
    panel:Connect(wx.wxEVT_PAINT,function()local dc=wx.wxPaintDC(panel);local gc=wx.wxGraphicsContext.Create(dc);local p=Themes.palettes[editor.theme];local size=panel:GetClientSize();local pen=wx.wxPen(Themes.colour(p.border),1,wx.wxPENSTYLE_SOLID);local brush=wx.wxBrush(Themes.colour(p.heading));gc:SetPen(pen);gc:SetBrush(brush);gc:DrawRoundedRectangle(.5,.5,size:GetWidth()-1,size:GetHeight()-1,4);gc:delete();pen:delete();brush:delete();dc:delete();end);return panel;
end
function Chrome.font(window,size,bold)local font=wx.wxFont(size or 9,wx.wxFONTFAMILY_DEFAULT,wx.wxFONTSTYLE_NORMAL,bold and wx.wxFONTWEIGHT_BOLD or wx.wxFONTWEIGHT_NORMAL,false,'Segoe UI');window:SetFont(font);font:delete();end
function Chrome.action(parent,name,label,editor,callback,role)
    role=role or 'toolbar';
    local panel=Themes.role(wx.wxPanel(parent,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(34,32)),role);panel:SetToolTip(label);local hover=false;
    panel:Connect(wx.wxEVT_PAINT,function()local dc=wx.wxPaintDC(panel);local gc=wx.wxGraphicsContext.Create(dc);local p=Themes.palettes[editor.theme];dc:SetBackground(wx.wxBrush(Themes.colour(p[role])));dc:Clear();local pen=wx.wxPen(Themes.colour(p.border),1,wx.wxPENSTYLE_SOLID);local brush=wx.wxBrush(Themes.colour(editor.tool==name and role=='rail' and p.active or hover and p.hover or p.field));gc:SetPen(pen);gc:SetBrush(brush);gc:DrawRoundedRectangle(.5,.5,33,31,4);gc:Translate(6,5);local stroke=wx.wxPen(Themes.colour(p.text),1,wx.wxPENSTYLE_SOLID);gc:SetPen(stroke);gc:SetBrush(wx.wxTRANSPARENT_BRUSH);
        local paths={move='M3 2L18 12L11 13L8 20Z',node='M4 4H18V18H4Z M4 4L18 18',text='M3 4H19 M11 4V20 M7 20H15',artistic='M3 20L11 3L19 20 M6 14H16',table='M3 3H19V19H3Z M3 8H19 M3 13H19 M8 3V19 M13 3V19',toc='M3 4H19 M3 9H14 M3 14H14 M3 19H19 M18 9H19 M18 14H19',image='M3 3H19V19H3Z M3 17L8 11L12 15L16 8L19 12',picture='M3 3H19V19H3Z M3 3L19 19 M19 3L3 19',line='M3 19L19 3',curve='M3 19Q3 3 11 11Q19 19 19 3',rectangle='M3 4H19V18H3Z',up='M4 14L11 7L18 14',down='M4 8L11 15L18 8',duplicate='M7 7H20V20H7Z M3 15V3H15',delete='M4 6H18 M8 6V3H14V6 M6 6V20H16V6 M9 9V17 M13 9V17'};
        if name=='picture-ellipse' then gc:DrawEllipse(2,2,18,18);gc:StrokeLine(5,5,17,17);gc:StrokeLine(17,5,5,17);elseif paths[name] then local path=require('Manual.Shapes').svgPath(gc,paths[name],20/22,20/22);gc:StrokePath(path);path:delete();else gc:DrawRoundedRectangle(4,9,11,10,1);local path=gc:CreatePath();path:MoveToPoint(6,9);path:AddLineToPoint(6,5);path:AddCurveToPoint(6,0,13,0,13,5);if name=='lock' then path:AddLineToPoint(13,9);end;gc:StrokePath(path);path:delete();end
        gc:delete();pen:delete();stroke:delete();brush:delete();dc:delete();end);
    panel:Connect(wx.wxEVT_ENTER_WINDOW,function(event)hover=true;panel:Refresh();event:Skip();end);panel:Connect(wx.wxEVT_LEAVE_WINDOW,function(event)hover=false;panel:Refresh();event:Skip();end);panel:Connect(wx.wxEVT_LEFT_UP,function()callback();end);return panel;
end
function Chrome.colour(parent,value,editor)
    local view=Themes.role(wx.wxPanel(parent,wx.wxID_ANY,wx.wxDefaultPosition,wx.wxSize(-1,26),wx.wxBORDER_NONE),'field');view:SetMinSize(wx.wxSize(-1,26));local control={view=view,value=value};
    function control:GetColour()return Themes.colour(self.value);end
    function control:SetColour(colour)self.value=string.format('#%02x%02x%02x',colour:Red(),colour:Green(),colour:Blue());view:Refresh();end
    function control:Connect(event,callback)if event==wx.wxEVT_COMMAND_COLOURPICKER_CHANGED then self.callback=callback;else view:Connect(event,callback);end;end
    view:Connect(wx.wxEVT_PAINT,function()local dc=wx.wxPaintDC(view);local gc=wx.wxGraphicsContext.Create(dc);local p=Themes.palettes[editor.theme];local size=view:GetClientSize();dc:SetBackground(wx.wxBrush(Themes.colour(p.field)));dc:Clear();local pen=wx.wxPen(Themes.colour(p.border),1,wx.wxPENSTYLE_SOLID);local brush=wx.wxBrush(Themes.colour(control.value));gc:SetPen(pen);gc:SetBrush(wx.wxBrush(Themes.colour(p.field)));gc:DrawRoundedRectangle(.5,.5,size:GetWidth()-1,size:GetHeight()-1,3);gc:SetBrush(brush);gc:DrawRectangle(4,4,size:GetWidth()-8,size:GetHeight()-8);gc:delete();pen:delete();brush:delete();dc:delete();end);
    view:Connect(wx.wxEVT_LEFT_UP,function()if not view:IsEnabled() then return;end;local data=wx.wxColourData();data:SetColour(control:GetColour());data:SetChooseFull(true);local dialog=wx.wxColourDialog(view,data);if dialog:ShowModal()==wx.wxID_OK then control:SetColour(dialog:GetColourData():GetColour());if control.callback then control.callback();end;end;dialog:Destroy();data:delete();end);return control;
end
function Chrome.shapes(button,editor)
    if editor.shapePopup then editor.shapePopup:Dismiss();editor.shapePopup:Destroy();end
    local popup=Themes.role(wx.wxPopupTransientWindow(button,wx.wxBORDER_SIMPLE),'panel');editor.shapePopup=popup;local outer=wx.wxBoxSizer(wx.wxVERTICAL);popup:SetSizer(outer);
    local list=require('Manual.Panes').create(popup,wx.wxSize(190,450),editor,'shapes',function(i)editor.tool=editor.shapeChoices.items[i].id;editor.editingObject=nil;editor.textObject=nil;editor.story=nil;popup:Dismiss();editor.refresh();editor.canvas.view:SetFocus();end);editor.shapeChoices=list;for _,spec in ipairs(require('Manual.Shapes').catalog)do list:Append(spec[2],nil,0,spec[1]);end;list:Flush();outer:Add(list.view,1,wx.wxEXPAND);popup:SetClientSize(wx.wxSize(190,450));popup:Layout();Themes.apply(popup,editor.theme);local position=button:GetScreenPosition();popup:Position(wx.wxPoint(position:GetX()+button:GetSize():GetWidth()+5,position:GetY()),wx.wxSize(0,0));popup:Popup(list.view);
end
function Chrome.menu(parent,editor,title,specs)
    if editor.contextPopup then editor.contextPopup:Dismiss();editor.contextPopup:Destroy();end
    local popup=Themes.role(wx.wxPopupTransientWindow(parent,wx.wxBORDER_SIMPLE),'panel');editor.contextPopup=popup;local outer=wx.wxBoxSizer(wx.wxVERTICAL);popup:SetSizer(outer);local heading=wx.wxStaticText(popup,wx.wxID_ANY,title);heading:Wrap(184);Chrome.font(heading,9,true);outer:Add(heading,0,wx.wxEXPAND+wx.wxALL,8);
    local list=require('Manual.Panes').create(popup,wx.wxSize(200,#specs*32),editor,'context',function(i)popup:Dismiss();specs[i][2]();end);editor.contextChoices=list;for _,spec in ipairs(specs)do list:Append(spec[1]);end;list:Flush();outer:Add(list.view,1,wx.wxEXPAND);popup:SetClientSize(wx.wxSize(200,#specs*32+heading:GetBestSize():GetHeight()+16));popup:Layout();Themes.apply(popup,editor.theme);popup:Position(wx.wxGetMousePosition(),wx.wxSize(0,0));popup:Popup(list.view);
end
return Chrome;
